@Service
public class SpmsApplicationService {
    private final DepartmentRepository departments; private final EmployeeRepository employees; private final UserRepository users;
    private final AttendanceRepository attendance; private final LeaveRepository leaves; private final PayrollRepository payroll;
    private final PerformanceRepository performance; private final ReportRepository reports; private final PayrollPaymentRepository payments; private final PasswordEncoder passwords;
    private final java.security.SecureRandom random=new java.security.SecureRandom();
    public SpmsApplicationService(DepartmentRepository departments,EmployeeRepository employees,UserRepository users,AttendanceRepository attendance,LeaveRepository leaves,PayrollRepository payroll,PerformanceRepository performance,ReportRepository reports,PayrollPaymentRepository payments,PasswordEncoder passwords){this.departments=departments;this.employees=employees;this.users=users;this.attendance=attendance;this.leaves=leaves;this.payroll=payroll;this.performance=performance;this.reports=reports;this.payments=payments;this.passwords=passwords;}

    @Transactional(readOnly=true) public List<Map<String,Object>> list(String view,String search,SpmsPrincipal actor){checkView(view,actor);String q=search==null?"":search.trim().toLowerCase(Locale.ROOT);List<Map<String,Object>> rows=switch(view){
        case "employees"->employees.findAll().stream().filter(e->inScope(e.id,actor)).map(this::employeeRow).toList();
        case "attendance"->attendance.findAllByOrderByWorkDateDesc().stream().filter(e->inScope(e.employee.id,actor)).map(this::attendanceRow).toList();
        case "leaves"->leaves.findAllByOrderByRequestedAtDesc().stream().filter(e->inScope(e.employee.id,actor)).map(this::leaveRow).toList();
        case "payroll"->payroll.findAllByOrderByPayMonthDesc().stream().filter(e->inScope(e.employee.id,actor)).map(this::payrollRow).toList();
        case "performance"->performance.findAllByOrderByEvaluatedAtDesc().stream().filter(e->inScope(e.employee.id,actor)).map(this::performanceRow).toList();
        case "departments"->departments.findAll().stream().map(this::departmentRow).toList();
        case "users"->users.findAll().stream().map(this::userRow).toList();
        case "reports"->reports.findAllByOrderByGeneratedAtDesc().stream().map(this::reportRow).toList();
        default->throw new IllegalArgumentException("Choose a valid SPMS workspace.");};
        if(!q.isBlank())rows=rows.stream().filter(r->r.values().stream().anyMatch(v->String.valueOf(v).toLowerCase(Locale.ROOT).contains(q))).toList();return rows;}

    @Transactional(readOnly=true) public Map<String,Object> dashboard(SpmsPrincipal actor){
        require("Dashboard",actor);LocalDate today=LocalDate.now();List<EmployeeEntity> people=employees.findAll().stream().filter(e->inScope(e.id,actor)).toList();
        long employeeCount=people.size(),active=people.stream().filter(e->"ACTIVE".equals(e.employmentStatus)).count();
        List<AttendanceEntity> todayRows=attendance.findAll().stream().filter(r->r.workDate.equals(today)&&inScope(r.employee.id,actor)).toList();
        long present=todayRows.stream().filter(r->"PRESENT".equals(r.status)).count(),absent=todayRows.stream().filter(r->"ABSENT".equals(r.status)).count();
        Set<String> leaveIds=new HashSet<>();todayRows.stream().filter(r->"LEAVE".equals(r.status)).forEach(r->leaveIds.add(r.employee.id));
        leaves.findAll().stream().filter(l->"APPROVED".equals(l.status)&&!today.isBefore(l.startDate)&&!today.isAfter(l.endDate)&&inScope(l.employee.id,actor)).forEach(l->leaveIds.add(l.employee.id));
        List<LeaveEntity> leaveRows=leaves.findAll().stream().filter(l->inScope(l.employee.id,actor)).toList();
        long pending=leaveRows.stream().filter(l->"PENDING".equals(l.status)).count(),approved=leaveRows.stream().filter(l->"APPROVED".equals(l.status)).count(),rejected=leaveRows.stream().filter(l->"REJECTED".equals(l.status)).count();
        BigDecimal attendancePercent=active==0?BigDecimal.ZERO:BigDecimal.valueOf(present).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(active),1,java.math.RoundingMode.HALF_UP);
        LocalDate monthStart=today.withDayOfMonth(1),monthEnd=monthStart.plusMonths(1).minusDays(1);
        List<PayrollEntity> currentPayroll=payroll.findAllByPayMonthBetween(monthStart,monthEnd).stream().filter(p->inScope(p.employee.id,actor)).toList();
        BigDecimal currentTotal=currentPayroll.stream().map(p->p.netSalary==null?p.basicSalary.add(p.allowances).subtract(p.deductions):p.netSalary).reduce(BigDecimal.ZERO,BigDecimal::add);
        long processed=currentPayroll.stream().filter(p->"PROCESSED".equals(p.status)||"PAID".equals(p.status)).count(),pendingPayroll=currentPayroll.stream().filter(p->"DRAFT".equals(p.status)).count();
        List<PerformanceEntity> evaluations=performance.findAll().stream().filter(p->inScope(p.employee.id,actor)).toList();
        BigDecimal average=evaluations.isEmpty()?BigDecimal.ZERO:evaluations.stream().map(p->p.rating).reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(evaluations.size()),1,java.math.RoundingMode.HALF_UP);
        long departmentCount=people.stream().filter(e->e.department!=null).map(e->e.department.id).distinct().count();
        LocalDate latestMonth=payroll.findAllByOrderByPayMonthDesc().stream().filter(p->inScope(p.employee.id,actor)).map(p->p.payMonth).findFirst().orElse(null);
        Map<String,Object> result=new LinkedHashMap<>();result.put("Total Employees",employeeCount);result.put("Active Employees",active);result.put("Department Count",departmentCount);
        result.put("Present Today",present);result.put("Absent Today",absent);result.put("On Leave",leaveIds.size());result.put("Attendance Percentage",attendancePercent);
        result.put("Pending Requests",pending);result.put("Approved Requests",approved);result.put("Rejected Requests",rejected);
        result.put("Payroll This Month",currentTotal);result.put("Payroll Period",currentPayroll.isEmpty()?(latestMonth==null?"Unavailable":latestMonth.format(DateTimeFormatter.ofPattern("yyyy-MM"))):monthStart.format(DateTimeFormatter.ofPattern("yyyy-MM")));
        result.put("Employees Processed",processed);result.put("Pending Payroll Records",pendingPayroll);result.put("Evaluations Completed",evaluations.size());result.put("Average Performance Rating",average);result.put("Employees Evaluated",evaluations.stream().map(p->p.employee.id).distinct().count());
        result.put("Department Distribution",departmentDistribution(actor));result.put("Recent Activity",recentActivity(actor));return result;
    }

    @Transactional public String addEmployee(Map<String,Object>b,SpmsPrincipal a){staff("Employee Management",a);EmployeeEntity e=new EmployeeEntity();String requested=Objects.toString(b.get("id"),"").trim();e.id=requested.isBlank()?nextEmployeeId():requested;if(employees.existsById(e.id))bad("That employee ID already exists.");e.name=required(b,"name");e.email=required(b,"email");if(!e.email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))bad("Enter a valid email address.");e.phone=required(b,"phone");if(!e.phone.matches("[+0-9() -]{7,24}"))bad("Enter a valid phone number.");e.gender=String.valueOf(b.getOrDefault("gender","Prefer not to say"));e.dateOfBirth=optionalDate(b.get("dateOfBirth"));e.address=String.valueOf(b.getOrDefault("address",""));e.designation=required(b,"designation");e.joiningDate=date(required(b,"joiningDate"));e.salary=money(required(b,"salary"));e.department=departmentByName(required(b,"department"));employees.save(e);return e.id;}
    @Transactional public void updateEmployee(String id,Map<String,Object>b,SpmsPrincipal a){staff("Employee Management",a);EmployeeEntity e=employee(id);e.name=required(b,"name");e.email=required(b,"email");if(!e.email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))bad("Enter a valid email address.");e.phone=required(b,"phone");if(!e.phone.matches("[+0-9() -]{7,24}"))bad("Enter a valid phone number.");e.gender=String.valueOf(b.getOrDefault("gender",e.gender));e.dateOfBirth=optionalDate(b.getOrDefault("dateOfBirth",e.dateOfBirth));e.address=String.valueOf(b.getOrDefault("address",e.address));e.designation=required(b,"designation");e.joiningDate=date(required(b,"joiningDate"));e.salary=money(required(b,"salary"));e.department=departmentByName(required(b,"department"));}
    @Transactional public void deleteEmployee(String id,SpmsPrincipal a){staff("Employee Management",a);employees.delete(employee(id));}
    @Transactional public void markAttendance(Map<String,Object>b,SpmsPrincipal a){require("Attendance & Leave",a);String id=scope(Objects.toString(b.get("employeeId"),""),a);LocalDate day=date(required(b,"workDate"));String state=required(b,"status").toUpperCase(Locale.ROOT);if(!Set.of("PRESENT","ABSENT","LEAVE").contains(state))bad("Choose a valid attendance status.");AttendanceEntity record=attendance.findAll().stream().filter(x->x.employee.id.equals(id)&&x.workDate.equals(day)).findFirst().orElseGet(AttendanceEntity::new);record.employee=employee(id);record.workDate=day;record.status=state;attendance.save(record);}
    @Transactional public void applyLeave(Map<String,Object>b,SpmsPrincipal a){require("Attendance & Leave",a);String id=scope(Objects.toString(b.get("employeeId"),""),a);EmployeeEntity person=employees.findForUpdate(id).orElseThrow(()->new IllegalArgumentException("Employee was not found."));LeaveEntity l=new LeaveEntity();l.employee=person;l.startDate=date(required(b,"from"));l.endDate=date(required(b,"to"));if(l.endDate.isBefore(l.startDate))bad("Leave end date must be on or after its start date.");if(l.startDate.isBefore(person.joiningDate))bad("Leave cannot begin before the employee's joining date.");l.leaveType=required(b,"type");if(!Set.of("CASUAL","SICK","ANNUAL","EMERGENCY","CASUAL LEAVE","SICK LEAVE","ANNUAL LEAVE","EMERGENCY LEAVE").contains(l.leaveType.toUpperCase(Locale.ROOT)))bad("Choose a supported leave type.");l.reason=required(b,"reason");if(l.reason.length()>500)bad("Leave reason must be 500 characters or fewer.");if(leaves.existsByEmployee_IdAndStatusInAndStartDateLessThanEqualAndEndDateGreaterThanEqual(id,List.of("PENDING","APPROVED"),l.endDate,l.startDate))bad("This date range overlaps an existing pending or approved leave request.");leaves.save(l);}
    @Transactional public void decideLeave(long id,Map<String,Object>b,SpmsPrincipal a){staff("Attendance & Leave",a);LeaveEntity l=leaves.findById(id).orElseThrow(()->new IllegalArgumentException("Leave request was not found."));if(!l.status.equals("PENDING"))bad("This leave request has already been reviewed.");Object decision=b.get("approve");if(!(decision instanceof Boolean))bad("Select approve or reject for this leave request.");boolean approve=(Boolean)decision;String note=Objects.toString(b.get("note"),"").trim();if(!approve&&note.isBlank())bad("Enter a rejection reason before rejecting this request.");if(note.length()>255)bad("Decision remarks must be 255 characters or fewer.");l.status=approve?"APPROVED":"REJECTED";l.reviewer=users.findById(a.id()).orElseThrow();l.reviewedAt=LocalDateTime.now();l.decisionNote=note;}
    @Transactional public void createPayroll(Map<String,Object>b,SpmsPrincipal a){staff("Payroll Management",a);PayrollEntity p=new PayrollEntity();p.employee=employee(required(b,"employeeId"));String month=required(b,"month");try{p.payMonth=YearMonth.parse(month).atDay(1);}catch(Exception ex){bad("Enter a valid payroll month as YYYY-MM.");}if(payroll.findAllByPayMonthBetween(p.payMonth,p.payMonth).stream().anyMatch(existing->existing.employee!=null&&Objects.equals(existing.employee.id,p.employee.id)))bad("Payroll already exists for this employee and month.");p.basicSalary=p.employee.salary;p.allowances=money(String.valueOf(b.getOrDefault("allowances","0")));p.deductions=money(String.valueOf(b.getOrDefault("deductions","0")));if(p.deductions.compareTo(p.basicSalary.add(p.allowances))>0)bad("Deductions cannot exceed salary and allowances.");p.netSalary=p.basicSalary.add(p.allowances).subtract(p.deductions);payroll.save(p);}
    @Transactional public void processPayroll(long id,SpmsPrincipal a){staff("Payroll Management",a);PayrollEntity p=payroll.findForUpdate(id).orElseThrow(()->new IllegalArgumentException("Payroll record was not found."));if(!"DRAFT".equals(p.status))bad("Only draft payroll records can be processed.");p.status="PROCESSED";}
    @Transactional public void markPaid(long id,Map<String,Object>b,SpmsPrincipal a){staff("Payroll Management",a);PayrollEntity p=payroll.findForUpdate(id).orElseThrow(()->new IllegalArgumentException("Payroll record was not found."));if("PAID".equals(p.status)||payments.existsByPayroll_IdAndStatus(id,"RECORDED"))bad("A payment has already been recorded for this payroll item.");if(!"PROCESSED".equals(p.status))bad("Process the payroll record before recording payment.");if(!Boolean.parseBoolean(String.valueOf(b.get("confirmExternally"))))bad("Confirm that the salary payment was processed outside SPMS.");String reference=Objects.toString(b.get("reference"),"").trim();if(reference.length()>100)bad("Payment reference must be 100 characters or fewer.");BigDecimal amount=p.basicSalary.add(p.allowances).subtract(p.deductions);if(amount.signum()<0)bad("Net salary cannot be negative.");UserEntity actor=users.findById(a.id()).orElseThrow();PayrollPaymentEntity payment=new PayrollPaymentEntity();payment.payroll=p;payment.initiatedBy=actor;payment.confirmedBy=actor;payment.amount=amount;payment.paymentReference=reference;payment.status="RECORDED";payments.save(payment);p.status="PAID";p.payDate=LocalDate.now();}
    @Transactional public void addPerformance(Map<String,Object>b,SpmsPrincipal a){staff("Performance & Reports",a);PerformanceEntity p=new PerformanceEntity();p.employee=employee(required(b,"employeeId"));setPerformanceFields(p,b);p.evaluator=users.findById(a.id()).orElseThrow();p.evaluatedAt=LocalDate.now();performance.save(p);}
    @Transactional public void updatePerformance(long id,Map<String,Object>b,SpmsPrincipal a){staff("Performance & Reports",a);PerformanceEntity p=performance.findById(id).orElseThrow(()->new IllegalArgumentException("Evaluation was not found."));setPerformanceFields(p,b);}
    @Transactional public void addDepartment(Map<String,Object>b,SpmsPrincipal a){admin(a);DepartmentEntity d=new DepartmentEntity();d.name=required(b,"name");d.description=String.valueOf(b.getOrDefault("description",""));departments.save(d);}
    @Transactional public void updateDepartment(int id,Map<String,Object>b,SpmsPrincipal a){admin(a);DepartmentEntity d=departments.findById(id).orElseThrow(()->new IllegalArgumentException("Department was not found."));d.name=required(b,"name");d.description=String.valueOf(b.getOrDefault("description",""));}
    @Transactional public void deleteDepartment(int id,SpmsPrincipal a){admin(a);DepartmentEntity d=departments.findById(id).orElseThrow(()->new IllegalArgumentException("Department was not found."));if(employees.findAll().stream().anyMatch(e->e.department!=null&&Objects.equals(e.department.id,id)))bad("Move the department's employees before deleting it.");departments.delete(d);}
    @Transactional public void addUser(Map<String,Object>b,SpmsPrincipal a){admin(a);String name=required(b,"username"),secret=required(b,"password"),role=required(b,"role");if(secret.length()<12)bad("Use a temporary password with at least 12 characters.");if(!Set.of("ADMIN","HR_MANAGER","EMPLOYEE").contains(role))bad("Choose a valid account role.");UserEntity u=new UserEntity();u.username=name;u.passwordHash=passwords.encode(secret);u.role=role;if(role.equals("EMPLOYEE")){u.employee=employee(required(b,"employeeId"));u.mustChangePassword=true;}users.save(u);}
    @Transactional public List<Map<String,String>> provisionEmployeeAccounts(SpmsPrincipal a){admin(a);List<UserEntity> current=users.findAll();Set<String> usernames=new HashSet<>();Set<String> linked=new HashSet<>();for(UserEntity u:current){usernames.add(u.username.toLowerCase(Locale.ROOT));if(u.employee!=null){if(!"EMPLOYEE".equals(u.role))bad("An employee is linked to a non-employee account. Review that account before provisioning.");linked.add(u.employee.id);}}
        List<Map<String,String>> credentials=new ArrayList<>();for(EmployeeEntity e:employees.findAll().stream().sorted(Comparator.comparing(x->x.id,String.CASE_INSENSITIVE_ORDER)).toList()){if(linked.contains(e.id))continue;String base="employee."+e.id.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9._-]","-");String username=base;int suffix=2;while(usernames.contains(username.toLowerCase(Locale.ROOT)))username=base+"."+(suffix++);String temporary=temporaryPassword();UserEntity u=new UserEntity();u.username=username;u.passwordHash=passwords.encode(temporary);u.role="EMPLOYEE";u.employee=e;u.active=true;u.mustChangePassword=true;users.save(u);usernames.add(username.toLowerCase(Locale.ROOT));linked.add(e.id);credentials.add(Map.of("employeeId",e.id,"employeeName",e.name,"username",username,"temporaryPassword",temporary));}return credentials;}
    @Transactional public List<Map<String,String>> resetEmployeePasswords(SpmsPrincipal a){admin(a);List<Map<String,String>> credentials=new ArrayList<>();for(UserEntity u:users.findAll().stream().filter(x->"EMPLOYEE".equals(x.role)&&x.active&&x.employee!=null).sorted(Comparator.comparing(x->x.employee.id,String.CASE_INSENSITIVE_ORDER)).toList()){String temporary=temporaryPassword();u.passwordHash=passwords.encode(temporary);u.mustChangePassword=true;Map<String,String> row=new LinkedHashMap<>();row.put("userId",String.valueOf(u.id));row.put("employeeId",u.employee.id);row.put("employeeName",u.employee.name);row.put("username",u.username);row.put("temporaryPassword",temporary);credentials.add(row);}return credentials;}
    @Transactional public Map<String,String> resetUserPassword(int id,SpmsPrincipal a){admin(a);if(id==a.id())bad("Sign in with a second Admin account to reset your own password.");UserEntity u=users.findById(id).orElseThrow(()->new IllegalArgumentException("User account was not found."));String temporary=temporaryPassword();u.passwordHash=passwords.encode(temporary);u.mustChangePassword=true;return Map.of("username",u.username,"temporaryPassword",temporary);}
    @Transactional public void setRole(int id,Map<String,Object>b,SpmsPrincipal a){admin(a);if(id==a.id())bad("Your active account role cannot be changed.");String role=required(b,"role");if(!Set.of("ADMIN","HR_MANAGER","EMPLOYEE").contains(role))bad("Choose a valid account role.");users.findById(id).orElseThrow(()->new IllegalArgumentException("User account was not found.")).role=role;}
    @Transactional public void setActive(int id,Map<String,Object>b,SpmsPrincipal a){admin(a);if(id==a.id())bad("You cannot deactivate your active account.");users.findById(id).orElseThrow(()->new IllegalArgumentException("User account was not found.")).active=Boolean.parseBoolean(String.valueOf(b.get("active")));}
    @Transactional public Map<String,Object> report(String type,Map<String,Object>b,SpmsPrincipal a){staff("Performance & Reports",a);String view=type.equals("leaves")?"leaves":type;if(!Set.of("employees","attendance","leaves","payroll","performance").contains(view))bad("Select a supported report type.");Map<String,Object> filters=b==null?Map.of():b;String filter=String.valueOf(filters.getOrDefault("filters",""));List<Map<String,Object>> rows=view.equals("attendance")?attendanceSummaryReport(filters,filter,a):list(view,filter,a);rows=applyReportFilters(rows,filters);ReportEntity r=new ReportEntity();r.reportType=switch(view){case "employees"->"EMPLOYEE";case "attendance"->"ATTENDANCE";case "leaves"->"LEAVE";case "payroll"->"PAYROLL";default->"PERFORMANCE";};r.requestedBy=users.findById(a.id()).orElseThrow();r.filterSummary=filter;reports.save(r);return Map.of("type",view,"count",rows.size(),"rows",rows);}

    private List<Map<String,Object>> attendanceSummaryReport(Map<String,Object> filters,String search,SpmsPrincipal actor){
        LocalDate end=filters.get("endDate")==null?LocalDate.now():date(String.valueOf(filters.get("endDate")));
        LocalDate start=filters.get("startDate")==null?end.minusDays(29):date(String.valueOf(filters.get("startDate")));
        if(end.isBefore(start))bad("Report end date must be on or after its start date.");
        String q=search==null?"":search.trim().toLowerCase(Locale.ROOT);Map<String,EmployeeEntity> people=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);Map<String,Map<LocalDate,String>> marks=new HashMap<>();Map<String,Set<LocalDate>> approvedLeaveDates=new HashMap<>();
        for(AttendanceEntity r:attendance.findAllByOrderByWorkDateDesc())if(!r.workDate.isBefore(start)&&!r.workDate.isAfter(end)&&inScope(r.employee.id,actor)&&matchesEmployee(r.employee,q)){people.put(r.employee.id,r.employee);marks.computeIfAbsent(r.employee.id,k->new HashMap<>()).put(r.workDate,r.status);}
        for(LeaveEntity l:leaves.findAll())if("APPROVED".equals(l.status)&&!l.endDate.isBefore(start)&&!l.startDate.isAfter(end)&&inScope(l.employee.id,actor)&&matchesEmployee(l.employee,q)){people.put(l.employee.id,l.employee);LocalDate from=l.startDate.isBefore(start)?start:l.startDate,to=l.endDate.isAfter(end)?end:l.endDate;Set<LocalDate> dates=approvedLeaveDates.computeIfAbsent(l.employee.id,k->new HashSet<>());for(LocalDate day=from;!day.isAfter(to);day=day.plusDays(1))if(day.getDayOfWeek().getValue()<=5)dates.add(day);}
        return people.values().stream().map(e->{Map<LocalDate,String> byDate=marks.getOrDefault(e.id,Map.of());Set<LocalDate> approved=approvedLeaveDates.getOrDefault(e.id,Set.of());long present=byDate.entrySet().stream().filter(x->"PRESENT".equals(x.getValue())&&!approved.contains(x.getKey())).count(),absent=byDate.entrySet().stream().filter(x->"ABSENT".equals(x.getValue())&&!approved.contains(x.getKey())).count(),legacyLeave=byDate.entrySet().stream().filter(x->"LEAVE".equals(x.getValue())&&!approved.contains(x.getKey())).count(),leave=approved.size()+legacyLeave;long working=present+absent;BigDecimal percent=working==0?BigDecimal.ZERO:BigDecimal.valueOf(present).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(working),1,java.math.RoundingMode.HALF_UP);return row("Employee ID",e.id,"Name",e.name,"Department",e.department==null?"Unassigned":e.department.name,"Reporting Period",start+" to "+end,"Present Days",present,"Absent Days",absent,"Half Days",0,"Approved Leave Days",leave,"Attendance Percentage",percent);}).toList();
    }
    private static boolean matchesEmployee(EmployeeEntity employee,String query){return query.isBlank()||employee.id.toLowerCase(Locale.ROOT).contains(query)||employee.name.toLowerCase(Locale.ROOT).contains(query);}
    private List<Map<String,Object>> applyReportFilters(List<Map<String,Object>> rows,Map<String,Object> filters){
        String employee=String.valueOf(filters.getOrDefault("employeeId","" )).trim().toLowerCase(Locale.ROOT),department=String.valueOf(filters.getOrDefault("department","")).trim().toLowerCase(Locale.ROOT),status=String.valueOf(filters.getOrDefault("status","")).trim().toLowerCase(Locale.ROOT),period=String.valueOf(filters.getOrDefault("payrollPeriod","")).trim();
        LocalDate start=filters.get("startDate")==null||String.valueOf(filters.get("startDate")).isBlank()?null:date(String.valueOf(filters.get("startDate")));
        LocalDate end=filters.get("endDate")==null||String.valueOf(filters.get("endDate")).isBlank()?null:date(String.valueOf(filters.get("endDate")));
        if(start!=null&&end!=null&&end.isBefore(start))bad("Report end date must be on or after its start date.");
        return rows.stream().filter(r->employee.isBlank()||String.valueOf(r.getOrDefault("Employee ID","")).toLowerCase(Locale.ROOT).equals(employee))
                .filter(r->department.isBlank()||String.valueOf(r.getOrDefault("Department","")).toLowerCase(Locale.ROOT).contains(department))
                .filter(r->status.isBlank()||String.valueOf(r.getOrDefault("Status","")).toLowerCase(Locale.ROOT).equals(status))
                .filter(r->period.isBlank()||String.valueOf(r.getOrDefault("Month","")).equals(period))
                .filter(r->{if(start==null&&end==null)return true;String a=String.valueOf(r.getOrDefault("FromDate",r.getOrDefault("Date",r.getOrDefault("Joining Date",r.getOrDefault("Month",""))))),z=String.valueOf(r.getOrDefault("ToDate",a));if(a.isBlank()||a.equals("null"))return true;try{LocalDate from=a.length()==7?YearMonth.parse(a).atDay(1):LocalDate.parse(a),to=z.length()==7?YearMonth.parse(z).atEndOfMonth():LocalDate.parse(z);return (start==null||!to.isBefore(start))&&(end==null||!from.isAfter(end));}catch(Exception ignored){return true;}}).toList();
    }

    private void checkView(String view,SpmsPrincipal a){String module=switch(view){case "employees"->"Employee Management";case "attendance","leaves"->"Attendance & Leave";case "payroll"->"Payroll Management";case "performance","reports"->"Performance & Reports";case "departments","users"->"Administration";default->throw new IllegalArgumentException("Unknown SPMS workspace.");};require(module,a);if((view.equals("users")||view.equals("departments"))&&!a.role().equals("ADMIN"))forbidden("Only an Admin can manage system administration.");if(view.equals("reports")&&a.role().equals("EMPLOYEE"))forbidden("Employee accounts cannot view system reports.");}
    private void require(String module,SpmsPrincipal a){if(a.role().equals("EMPLOYEE")&&!Set.of("Dashboard","Employee Management","Attendance & Leave","Payroll Management","Performance & Reports").contains(module))forbidden("Your account is not authorized for this module.");}
    private void staff(String module,SpmsPrincipal a){require(module,a);if(a.role().equals("EMPLOYEE"))forbidden("Employee accounts cannot manage this workflow.");}
    private void admin(SpmsPrincipal a){if(!a.role().equals("ADMIN"))forbidden("Only an Admin can manage system administration.");}
    private boolean inScope(String employeeId,SpmsPrincipal a){return !a.role().equals("EMPLOYEE")||Objects.equals(employeeId,a.employeeId());}
    private String departmentDistribution(SpmsPrincipal actor){List<EmployeeEntity> people=employees.findAll().stream().filter(e->inScope(e.id,actor)&&"ACTIVE".equals(e.employmentStatus)).toList();return departments.findAll().stream().sorted(Comparator.comparing(d->Objects.toString(d.name,""),String.CASE_INSENSITIVE_ORDER)).map(d->Objects.toString(d.name,"Unassigned")+"="+people.stream().filter(e->e.department!=null&&Objects.equals(e.department.id,d.id)).count()).reduce((x,y)->x+"|"+y).orElse("");}
    private String recentActivity(SpmsPrincipal actor){return leaves.findAllByOrderByRequestedAtDesc().stream().filter(l->inScope(l.employee.id,actor)).limit(5).map(l->"Leave request "+l.id+" · "+l.status).reduce((x,y)->x+"|"+y).orElse("");}
    private String scope(String requested,SpmsPrincipal a){if(a.role().equals("EMPLOYEE")){if(a.employeeId()==null||a.employeeId().isBlank())forbidden("This account is not linked to an employee record.");return a.employeeId();}if(requested==null||requested.isBlank())bad("Select an employee record.");return requested.trim();}
    private EmployeeEntity employee(String id){return employees.findById(id).orElseThrow(()->new IllegalArgumentException("Employee was not found."));}
    private DepartmentEntity departmentByName(String name){return departments.findByNameIgnoreCase(name).orElseThrow(()->new IllegalArgumentException("Department was not found. Add it in Administration first."));}
    private static String required(Map<String,Object>b,String key){Object raw=b.get(key);String v=raw==null?"":String.valueOf(raw).trim();if(v.isBlank())bad("Complete all required fields.");return v;}
    private static LocalDate date(String value){try{return LocalDate.parse(value);}catch(Exception ex){bad("Enter a valid date as YYYY-MM-DD.");return null;}}
    private static LocalDate optionalDate(Object raw){if(raw==null||String.valueOf(raw).isBlank())return null;return date(String.valueOf(raw));}
    private static BigDecimal money(String v){try{BigDecimal n=new BigDecimal(v);if(n.signum()<0)throw new NumberFormatException();return n;}catch(Exception ex){bad("Enter a valid non-negative amount.");return null;}}
    private static BigDecimal rating(String v){try{BigDecimal n=new BigDecimal(v);if(n.compareTo(BigDecimal.ONE)<0||n.compareTo(BigDecimal.valueOf(5))>0)throw new NumberFormatException();return n.setScale(1,java.math.RoundingMode.HALF_UP);}catch(Exception ex){bad("Rating must be between 1 and 5.");return null;}}
    private static void bad(String message){throw new IllegalArgumentException(message);}private static void forbidden(String message){throw new org.springframework.security.access.AccessDeniedException(message);}
    private Map<String,Object> employeeRow(EmployeeEntity e){return row("Employee ID",e.id,"Name",e.name,"Department",e.department==null?"Unassigned":e.department.name,"Designation",e.designation,"Email",e.email,"Phone",e.phone,"Gender",e.gender,"Date of Birth",e.dateOfBirth,"Address",e.address,"Joining Date",e.joiningDate,"Status",e.employmentStatus,"Salary",e.salary);}
    private Map<String,Object> attendanceRow(AttendanceEntity e){return row("ID",e.id,"Date",e.workDate,"Employee ID",e.employee.id,"Employee",e.employee.name,"Status",e.status,"Check In",e.checkIn,"Check Out",e.checkOut);}
    private Map<String,Object> leaveRow(LeaveEntity e){return row("ID",e.id,"Employee ID",e.employee.id,"Employee",e.employee.name,"Department",e.employee.department==null?"Unassigned":e.employee.department.name,"Type",e.leaveType,"FromDate",e.startDate,"ToDate",e.endDate,"Reason",e.reason,"Applied Date",e.requestedAt,"Status",e.status,"Reviewer",e.reviewer==null?"Pending review":e.reviewer.username,"Reviewed Date",e.reviewedAt,"Decision Note",e.decisionNote);}
    private Map<String,Object> payrollRow(PayrollEntity e){PayrollPaymentEntity payment=payments.findFirstByPayroll_IdAndStatusOrderByConfirmedAtDesc(e.id,"RECORDED").orElse(null);return row("ID",e.id,"Employee ID",e.employee.id,"Employee",e.employee.name,"Department",e.employee.department==null?"Unassigned":e.employee.department.name,"Month",e.payMonth.format(DateTimeFormatter.ofPattern("yyyy-MM")),"Basic",e.basicSalary,"Allowances",e.allowances,"Deductions",e.deductions,"Net Salary",e.netSalary==null?e.basicSalary.add(e.allowances).subtract(e.deductions):e.netSalary,"Status",e.status,"Payment Date",e.payDate,"Payment Reference",payment==null?"":payment.paymentReference,"Payment Recorded At",payment==null?null:payment.confirmedAt,"Payment Recorded By",payment==null?"":payment.confirmedBy.username,"Payment Record",payment==null?"":payment.status);}
    private Map<String,Object> performanceRow(PerformanceEntity e){return row("ID",e.id,"Employee ID",e.employee.id,"Employee",e.employee.name,"Department",e.employee.department==null?"Unassigned":e.employee.department.name,"Designation",e.employee.designation,"Period",e.period,"Technical Skills",e.technicalSkillsScore,"Communication",e.communicationScore,"Teamwork",e.teamworkScore,"Productivity",e.productivityScore,"Quality of Work",e.qualityScore,"Rating",e.rating,"Evaluator",e.evaluator==null?"Unavailable":e.evaluator.username,"Remarks",e.remarks,"Improvement Suggestions",e.improvementSuggestions,"Future Goals",e.futureGoals,"Date",e.evaluatedAt);}
    private Map<String,Object> departmentRow(DepartmentEntity d){return row("ID",d.id,"Department",d.name,"Description",d.description,"Employee Count",employees.findAll().stream().filter(e->e.department!=null&&Objects.equals(e.department.id,d.id)).count());}
    private Map<String,Object> userRow(UserEntity u){return row("ID",u.id,"Username",u.username,"Role",u.role,"Employee ID",u.employee==null?"":u.employee.id,"Active",u.active,"Must Change Password",u.mustChangePassword);}
    private Map<String,Object> reportRow(ReportEntity r){return row("ID",r.id,"Type",r.reportType,"Generated",r.generatedAt,"Filters",r.filterSummary);}
    private static Map<String,Object> row(Object... fields){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<fields.length;i+=2)m.put(String.valueOf(fields[i]),fields[i+1]);return m;}
    private String nextEmployeeId(){int max=employees.findAll().stream().map(e->e.id).filter(id->id!=null&&id.matches("EMP\\d+")).mapToInt(id->{try{return Integer.parseInt(id.substring(3));}catch(NumberFormatException ex){return 1000;}}).max().orElse(1000);String candidate;do{candidate="EMP"+(++max);}while(employees.existsById(candidate));return candidate;}
    private void setPerformanceFields(PerformanceEntity p,Map<String,Object>b){p.period=required(b,"period");if(p.period.length()>30)bad("Evaluation period must be 30 characters or fewer.");p.technicalSkillsScore=rating(required(b,"technicalSkills"));p.communicationScore=rating(required(b,"communication"));p.teamworkScore=rating(required(b,"teamwork"));p.productivityScore=rating(required(b,"productivity"));p.qualityScore=rating(required(b,"qualityOfWork"));p.rating=p.technicalSkillsScore.add(p.communicationScore).add(p.teamworkScore).add(p.productivityScore).add(p.qualityScore).divide(BigDecimal.valueOf(5),1,java.math.RoundingMode.HALF_UP);p.remarks=required(b,"remarks");p.improvementSuggestions=required(b,"improvementSuggestions");p.futureGoals=required(b,"futureGoals");if(p.remarks.length()>1000||p.improvementSuggestions.length()>1000||p.futureGoals.length()>1000)bad("Performance comments and goals must be 1,000 characters or fewer.");}
    private String temporaryPassword(){byte[] secret=new byte[24];random.nextBytes(secret);return java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(secret);}
}
